<!doctype html>
<html lang="da">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="#080a10">
<title>Revive Gaming · Game Server Hosting</title>
<meta name="description" content="Game server hosting med hurtig provisionering, DDoS-beskyttelse og Nodexa kontrolpanel.">
<style>
:root{color-scheme:dark;--bg:#07090e;--surface:#0e121b;--surface2:#131824;--line:#242b3a;--text:#f4f6fb;--muted:#929caf;--purple:#745cff;--purple2:#9a6dff;--green:#34d399;--red:#fb7185;--shadow:0 30px 90px rgba(0,0,0,.38)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 20% -10%,rgba(112,76,255,.21),transparent 34%),radial-gradient(circle at 86% 16%,rgba(74,45,180,.11),transparent 25%),var(--bg);color:var(--text);font:14px Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{width:min(1180px,calc(100% - 32px));margin:auto}a{text-decoration:none;color:inherit}button,input,select{font:inherit}.topbar{height:76px;border-bottom:1px solid rgba(37,44,58,.76);background:rgba(7,9,14,.78);backdrop-filter:blur(18px);position:sticky;top:0;z-index:30}.topin{height:100%;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{display:flex;align-items:center;gap:11px;font-weight:900;letter-spacing:.11em;font-size:19px}.mark{width:39px;height:39px;border-radius:11px;display:grid;place-items:center;background:linear-gradient(135deg,var(--purple),var(--purple2));box-shadow:0 10px 30px rgba(117,92,255,.27)}.brand span{color:#9a7cff}.nav{display:flex;align-items:center;gap:26px;color:#aeb6c6;font-size:13px}.nav a:hover{color:#fff}.actions{display:flex;gap:9px}.btn{border:1px solid var(--line);background:#131925;color:#e8ebf1;border-radius:10px;padding:10px 14px;font-weight:800;cursor:pointer}.btn:hover{border-color:#3b455a}.primary{border:0;background:linear-gradient(135deg,#6651f2,#8a61ff);color:#fff;box-shadow:0 12px 32px rgba(112,83,255,.24)}.cartBtn{position:relative}.cartCount{position:absolute;right:-7px;top:-7px;min-width:19px;height:19px;border-radius:20px;background:#8a61ff;display:grid;place-items:center;font-size:10px;font-weight:900;padding:0 5px}.hero{padding:92px 0 58px}.heroGrid{display:grid;grid-template-columns:1.05fr .95fr;gap:64px;align-items:center}.pill{display:inline-flex;align-items:center;gap:8px;border:1px solid #342d5d;border-radius:999px;background:#151127;color:#b9aaff;padding:7px 11px;font-size:11px;font-weight:800;letter-spacing:.04em}.dot{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 0 4px rgba(52,211,153,.10)}h1{font-size:clamp(42px,6vw,72px);line-height:1.02;letter-spacing:-.045em;margin:18px 0 18px}.grad{background:linear-gradient(100deg,#fff 5%,#b8a9ff 58%,#8069ff);-webkit-background-clip:text;background-clip:text;color:transparent}.hero p{font-size:18px;line-height:1.65;color:#a4adbd;max-width:650px;margin:0 0 28px}.heroCtas{display:flex;gap:11px;flex-wrap:wrap}.heroCtas .btn{padding:13px 18px}.trust{display:flex;gap:26px;flex-wrap:wrap;margin-top:31px;color:#8d97a8;font-size:12px}.trust b{color:#eef1f6}.preview{position:relative}.glow{position:absolute;inset:12% 8%;background:#6f55ff;filter:blur(100px);opacity:.24}.panelPreview{position:relative;border:1px solid #2b3342;border-radius:20px;background:linear-gradient(180deg,#111722,#0b0f16);box-shadow:var(--shadow);overflow:hidden;transform:perspective(1100px) rotateY(-5deg) rotateX(2deg)}.pTop{height:55px;border-bottom:1px solid #242c3a;display:flex;align-items:center;padding:0 17px;gap:7px}.pDot{width:8px;height:8px;border-radius:50%;background:#394151}.pBody{display:grid;grid-template-columns:115px 1fr;min-height:360px}.pSide{border-right:1px solid #232b38;padding:15px 11px}.pNav{height:28px;border-radius:7px;background:#171d28;margin-bottom:8px}.pNav.active{background:#241f43;border-left:3px solid #7b63ff}.pMain{padding:20px}.serverHead{display:flex;justify-content:space-between;gap:10px}.fake{background:#1a202b;border-radius:7px}.fake.title{width:140px;height:16px}.fake.small{width:82px;height:9px;margin-top:8px}.status{padding:5px 8px;border-radius:20px;background:#10271f;color:#70e6b9;font-size:8px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.stat{height:62px;border:1px solid #242c39;border-radius:9px;background:#10151e;padding:10px}.bar{height:6px;border-radius:6px;background:#242b37;margin-top:13px;overflow:hidden}.bar:after{content:"";display:block;height:100%;width:62%;background:#755eff}.console{height:156px;border:1px solid #252d3a;border-radius:9px;background:#080b10;padding:12px}.line{height:7px;border-radius:5px;background:#28303c;margin-bottom:8px;width:78%}.line:nth-child(2){width:58%}.line:nth-child(3){width:90%}.line:nth-child(4){width:44%;background:#1d5e49}.section{padding:62px 0}.sectionHead{text-align:center;max-width:720px;margin:0 auto 34px}.eyebrow{color:#8c74ff;font-size:11px;font-weight:900;letter-spacing:.16em}.section h2{font-size:38px;letter-spacing:-.03em;margin:8px 0 10px}.sectionHead p{color:var(--muted);line-height:1.65}.products{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.product{border:1px solid var(--line);background:linear-gradient(180deg,#111620,#0d1119);border-radius:16px;padding:22px;position:relative;overflow:hidden}.product:before{content:"";position:absolute;width:140px;height:140px;border-radius:50%;background:#7258ff;filter:blur(80px);opacity:.08;right:-40px;top:-50px}.productIcon{width:45px;height:45px;border-radius:11px;background:#1b1832;display:grid;place-items:center;font-size:22px}.product h3{font-size:21px;margin:17px 0 5px}.product p{color:var(--muted);line-height:1.55;min-height:44px}.price{font-size:31px;font-weight:900;margin:20px 0 3px}.price small{font-size:12px;color:#8f99aa;font-weight:600}.features{display:grid;gap:9px;margin:20px 0;color:#b5bdca;font-size:12px}.features div:before{content:"✓";color:#69ddb4;font-weight:900;margin-right:8px}.product .btn{width:100%;margin-top:5px}.popular{border-color:#5b4bb0;box-shadow:0 20px 60px rgba(86,66,201,.12)}.badge{position:absolute;right:15px;top:15px;background:#2a2252;color:#b6a6ff;border:1px solid #51418e;border-radius:999px;padding:5px 8px;font-size:9px;font-weight:900}.featureGrid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.feature{border:1px solid var(--line);border-radius:14px;background:#0d121a;padding:20px}.feature b{display:block;font-size:15px;margin:11px 0 6px}.feature p{margin:0;color:var(--muted);line-height:1.5;font-size:12px}.bigCta{border:1px solid #3a315d;background:linear-gradient(120deg,#151127,#10141e);border-radius:20px;padding:42px;display:flex;justify-content:space-between;gap:25px;align-items:center;box-shadow:var(--shadow)}.bigCta h2{margin:0 0 8px}.bigCta p{margin:0;color:var(--muted)}footer{border-top:1px solid var(--line);padding:36px 0 48px;margin-top:60px;color:#7f899b}.footerIn{display:flex;justify-content:space-between;gap:25px;flex-wrap:wrap}.footerLinks{display:flex;gap:20px}.mobileMenu{display:none}
/* cart / checkout */.subPage{padding:52px 0 90px}.subTitle{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:25px}.subTitle h1{font-size:38px;margin:0}.subTitle p{color:var(--muted);margin:7px 0 0}.cartGrid{display:grid;grid-template-columns:1fr 350px;gap:20px}.card{border:1px solid var(--line);background:#10151e;border-radius:15px}.cartList{padding:8px 18px}.cartItem{display:grid;grid-template-columns:1fr auto;gap:20px;padding:18px 2px;border-bottom:1px solid var(--line)}.cartItem:last-child{border:0}.cartItem h3{margin:0 0 5px}.cartItem p{margin:0;color:var(--muted);font-size:12px}.cartPrice{font-weight:900;font-size:17px;text-align:right}.remove{border:0;background:none;color:#fb8ba0;cursor:pointer;font-size:11px;margin-top:7px}.summaryCard{padding:21px;height:max-content}.summaryCard h3{margin:0 0 16px}.sumrow{display:flex;justify-content:space-between;gap:15px;padding:10px 0;color:#adb5c4;border-bottom:1px solid var(--line)}.sumrow.total{border:0;color:white;font-size:17px;font-weight:900;padding-top:16px}.summaryCard .btn{width:100%;margin-top:13px;padding:12px}.empty{padding:45px;text-align:center;color:var(--muted)}.checkoutGrid{display:grid;grid-template-columns:1fr 370px;gap:20px}.formCard{padding:23px}.formCard h2{font-size:20px;margin:0 0 18px}.formGrid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.wide{grid-column:1/-1}label span{display:block;color:#a6afbf;font-size:11px;font-weight:700;margin-bottom:7px}input,select{width:100%;padding:12px;border-radius:9px;border:1px solid #293243;background:#090d14;color:white;outline:none}input:focus,select:focus{border-color:#6e5bdf;box-shadow:0 0 0 3px rgba(110,91,223,.12)}.payment{border:1px dashed #3a4251;border-radius:11px;padding:16px;color:#9aa5b6;line-height:1.55;font-size:12px;margin-top:18px}.notice{background:#17132a;border:1px solid #3e3466;color:#bcb0e8;padding:12px 14px;border-radius:10px;margin-top:14px;font-size:12px;line-height:1.5}
@media(max-width:900px){.nav{display:none}.mobileMenu{display:inline-flex}.hero{padding-top:58px}.heroGrid,.cartGrid,.checkoutGrid{grid-template-columns:1fr}.preview{order:-1}.panelPreview{transform:none}.products{grid-template-columns:1fr}.featureGrid{grid-template-columns:1fr 1fr}.bigCta{align-items:flex-start;flex-direction:column}.summaryCard{order:-1}.topbar .actions .portal{display:none}}
@media(max-width:560px){.wrap{width:min(100% - 22px,1180px)}.topbar{height:66px}.brand{font-size:16px}.mark{width:34px;height:34px}.hero h1{font-size:42px}.hero p{font-size:15px}.pBody{grid-template-columns:90px 1fr}.stats{grid-template-columns:1fr}.stat:nth-child(n+2){display:none}.featureGrid{grid-template-columns:1fr}.section{padding:45px 0}.section h2{font-size:31px}.bigCta{padding:27px}.formGrid{grid-template-columns:1fr}.wide{grid-column:auto}.subTitle{align-items:flex-start;flex-direction:column}}
</style>
</head>
<body>
<header class="topbar"><div class="wrap topin"><a class="brand" href="/"><span class="mark">R</span><div>REVIVE<span>GAMING</span></div></a><nav class="nav"><a href="/#hosting">Game Hosting</a><a href="/#features">Fordele</a><a href="/#network">Netværk</a><a href="/#faq">FAQ</a></nav><div class="actions"><a class="btn portal" href="{{ rtrim(config('app.url'), '/') }}">Kundeportal</a><a class="btn cartBtn" href="/cart">Kurv <span id="cartCount" class="cartCount">0</span></a></div></div></header>
<main id="app"></main>
<footer><div class="wrap footerIn"><div><div class="brand" style="font-size:15px"><span class="mark" style="width:31px;height:31px">R</span><div>REVIVE<span>GAMING</span></div></div><p style="font-size:11px">Powered by Nodexa Hosting Platform.</p></div><div class="footerLinks"><a href="/#hosting">Produkter</a><a href="/#faq">FAQ</a><a href="{{ rtrim(config('app.url'), '/') }}">Panel</a></div></div></footer>
<script>
const PRODUCTS={
 fivem:{id:'fivem',name:'FiveM Performance',desc:'Optimeret FiveM hosting med NVMe og hurtig CPU.',price:129,unit:'md.',icon:'◆',features:['4 vCPU high-frequency','8 GB RAM','50 GB NVMe','DDoS-beskyttelse','Nodexa Game Panel']},
 minecraft:{id:'minecraft',name:'Minecraft Pro',desc:'Minecraft hosting til vanilla, plugins og modpacks.',price:79,unit:'md.',icon:'⬡',features:['3 vCPU','6 GB RAM','35 GB NVMe','Automatiske backups','Nodexa Game Panel']},
 vps:{id:'vps',name:'Cloud VPS',desc:'Fleksibel Linux VPS til bots, websites og services.',price:99,unit:'md.',icon:'▣',features:['4 vCPU','8 GB RAM','80 GB NVMe','1 Gbit netværk','Root adgang']}
};
const money=n=>new Intl.NumberFormat('da-DK',{style:'currency',currency:'DKK',maximumFractionDigits:0}).format(n);
const readCart=()=>{try{return JSON.parse(localStorage.getItem('revive_cart')||'[]')}catch{return[]}};
const writeCart=c=>{localStorage.setItem('revive_cart',JSON.stringify(c));updateCount()};
const updateCount=()=>{const e=document.getElementById('cartCount');if(e)e.textContent=String(readCart().length)};
function add(id){const c=readCart();if(!c.includes(id))c.push(id);writeCart(c);location.href='/cart'}
function removeItem(id){writeCart(readCart().filter(x=>x!==id));render()}
function total(){return readCart().reduce((s,id)=>s+(PRODUCTS[id]?.price||0),0)}
function productCard(p,pop=false){return `<article class="product ${pop?'popular':''}">${pop?'<span class="badge">MEST POPULÆR</span>':''}<div class="productIcon">${p.icon}</div><h3>${p.name}</h3><p>${p.desc}</p><div class="price">${money(p.price)} <small>/ ${p.unit}</small></div><div class="features">${p.features.map(x=>`<div>${x}</div>`).join('')}</div><button class="btn primary" onclick="add('${p.id}')">Vælg løsning</button></article>`}
function home(){return `<section class="hero"><div class="wrap heroGrid"><div><span class="pill"><i class="dot"></i> Hosting bygget til gaming</span><h1>Din server. <span class="grad">Klar på få minutter.</span></h1><p>Performance game hosting med moderne hardware, DDoS-beskyttelse og ét samlet Nodexa kontrolpanel til servere, filer, databaser, backups og brugere.</p><div class="heroCtas"><a class="btn primary" href="#hosting">Se game hosting</a><a class="btn" href="{{ rtrim(config('app.url'), '/') }}">Åbn kundeportal</a></div><div class="trust"><span><b>99.9%</b> mål for oppetid</span><span><b>NVMe</b> storage</span><span><b>Automatisk</b> provisionering</span></div></div><div class="preview"><div class="glow"></div><div class="panelPreview"><div class="pTop"><i class="pDot"></i><i class="pDot"></i><i class="pDot"></i></div><div class="pBody"><aside class="pSide"><div class="pNav active"></div><div class="pNav"></div><div class="pNav"></div><div class="pNav"></div><div class="pNav"></div></aside><div class="pMain"><div class="serverHead"><div><div class="fake title"></div><div class="fake small"></div></div><span class="status">ONLINE</span></div><div class="stats"><div class="stat"><div class="fake small"></div><div class="bar"></div></div><div class="stat"><div class="fake small"></div><div class="bar"></div></div><div class="stat"><div class="fake small"></div><div class="bar"></div></div></div><div class="console"><div class="line"></div><div class="line"></div><div class="line"></div><div class="line"></div></div></div></div></div></div></div></section>
<section class="section" id="hosting"><div class="wrap"><div class="sectionHead"><div class="eyebrow">HOSTING</div><h2>Vælg din server</h2><p>Start med en løsning og skalér senere. Alle game-server produkter administreres direkte i Nodexa.</p></div><div class="products">${productCard(PRODUCTS.minecraft)}${productCard(PRODUCTS.fivem,true)}${productCard(PRODUCTS.vps)}</div></div></section>
<section class="section" id="features"><div class="wrap"><div class="sectionHead"><div class="eyebrow">NODEXA PLATFORM</div><h2>Alt samlet ét sted</h2><p>Ingen separate logins til website, game panel og databaseværktøjer.</p></div><div class="featureGrid"><div class="feature"><div>⚡</div><b>Hurtig provisionering</b><p>Nye servere kan oprettes automatisk på en ledig Node efter bestilling.</p></div><div class="feature"><div>⌘</div><b>Game Panel</b><p>Konsol, filer, databaser, schedules, backups og subusers.</p></div><div class="feature"><div>◈</div><b>Database Hosting</b><p>Separate databasebrugere og credentials direkte fra serverpanelet.</p></div><div class="feature"><div>✓</div><b>Overvågning</b><p>Nodexa holder øje med Nodes og viser systemfejl i Admin Panel.</p></div></div></div></section>
<section class="section" id="network"><div class="wrap"><div class="bigCta"><div><div class="eyebrow">REVIVE GAMING</div><h2>Klar til at starte?</h2><p>Vælg din løsning og fortsæt til checkout.</p></div><a class="btn primary" href="#hosting">Se produkter</a></div></div></section>
<section class="section" id="faq"><div class="wrap"><div class="sectionHead"><div class="eyebrow">FAQ</div><h2>Ofte stillede spørgsmål</h2></div><div class="featureGrid"><div class="feature"><b>Hvor hurtigt er serveren klar?</b><p>Når automatisk provisionering er slået til, oprettes serveren straks efter en godkendt ordre.</p></div><div class="feature"><b>Kan jeg opgradere senere?</b><p>Ja. Ressourcer og plan kan ændres uden at skifte kontrolpanel.</p></div><div class="feature"><b>Har jeg adgang til filer?</b><p>Ja. Nodexa indeholder filhåndtering og serverkontrol.</p></div><div class="feature"><b>Hvor logger jeg ind?</b><p>Kundeportal og game panel ligger på {{ parse_url(config('app.url'), PHP_URL_HOST) }}.</p></div></div></div></section>`}
function cart(){const c=readCart();return `<section class="subPage"><div class="wrap"><div class="subTitle"><div><div class="eyebrow">DIN BESTILLING</div><h1>Kurv</h1><p>Kontrollér dine produkter før checkout.</p></div><a class="btn" href="/#hosting">+ Tilføj produkt</a></div><div class="cartGrid"><div class="card cartList">${c.length?c.map(id=>{const p=PRODUCTS[id];return p?`<div class="cartItem"><div><h3>${p.name}</h3><p>${p.desc}</p></div><div><div class="cartPrice">${money(p.price)} / md.</div><button class="remove" onclick="removeItem('${p.id}')">Fjern</button></div></div>`:''}).join(''):'<div class="empty">Din kurv er tom.</div>'}</div><aside class="card summaryCard"><h3>Ordreoversigt</h3><div class="sumrow"><span>Produkter</span><b>${c.length}</b></div><div class="sumrow"><span>Fakturering</span><b>Månedligt</b></div><div class="sumrow total"><span>I alt</span><span>${money(total())}</span></div>${c.length?'<a class="btn primary" href="/checkout">Gå til checkout</a>':'<a class="btn" href="/#hosting">Se produkter</a>'}</aside></div></div></section>`}
function checkout(){const c=readCart();if(!c.length)return cart();return `<section class="subPage"><div class="wrap"><div class="subTitle"><div><div class="eyebrow">CHECKOUT</div><h1>Færdiggør bestilling</h1><p>Indtast kundeoplysninger. Betalingsudbydere kobles på gennem Nodexa Billing.</p></div></div><div class="checkoutGrid"><div class="card formCard"><h2>Kundeoplysninger</h2><div class="formGrid"><label><span>Fornavn</span><input placeholder="Fornavn"></label><label><span>Efternavn</span><input placeholder="Efternavn"></label><label class="wide"><span>E-mail</span><input type="email" placeholder="dig@example.com"></label><label><span>Land</span><select><option>Danmark</option><option>Sverige</option><option>Norge</option><option>Tyskland</option></select></label><label><span>Telefon</span><input placeholder="+45"></label></div><div class="payment"><b>Betaling</b><br>Stripe/PayPal checkout aktiveres, når betalingsmodulet er konfigureret i Nodexa Admin.</div><div class="notice">Storefronten er aktiv, men automatisk betaling og ordreprovisionering kræver det kommende Billing/Orders-modul. Der oprettes derfor ikke en rigtig ordre fra denne knap endnu.</div><button class="btn primary" style="width:100%;margin-top:16px" onclick="alert('Billing-modulet er ikke aktiveret endnu.')">Fortsæt til betaling</button></div><aside class="card summaryCard"><h3>Din ordre</h3>${c.map(id=>{const p=PRODUCTS[id];return p?`<div class="sumrow"><span>${p.name}</span><b>${money(p.price)}</b></div>`:''}).join('')}<div class="sumrow total"><span>I alt / md.</span><span>${money(total())}</span></div><a class="btn" href="/cart">Tilbage til kurv</a></aside></div></div></section>`}
function render(){const p=location.pathname.replace(/\/+$/,'')||'/';document.getElementById('app').innerHTML=p==='/cart'?cart():p==='/checkout'?checkout():home();updateCount()}
render();updateCount();
</script>
</body>
</html>
